module priority32 (
    input wire clk,
    input wire rst_n,
    input wire valid_i,
    input wire [31:0] a_i,
    input wire [31:0] b_i,
    output reg valid_o,
    output reg [5:0] y_o
);

// ---- nibble occupancy (depth 1) ----
wire nA = |a_i[31:28];
wire nB = |a_i[27:24];
wire nC = |a_i[23:20];
wire nD = |a_i[19:16];
wire nE = |a_i[15:12];
wire nF = |a_i[11:8];
wire nG = |a_i[7:4];
wire nH = |a_i[3:0];

wire hit = nA | nB | nC | nD | nE | nF | nG | nH;

// ---- nibble index bits (depth 2..4) ----
wire s2 = nA | nB | nC | nD;                                     // idx[4]
wire s1 = (nA | nB) | (~(nC | nD) & (nE | nF));                  // idx[3]
wire s0 = nA | (~nB & nC)
             | (~(nB | nC | nD) & nE)
             | (~(nB | nC | nD) & ~(nE | nF) & nG);              // idx[2]

// ---- per-nibble low index bits, all in parallel (depth 1..2) ----
wire [15:0] q;
assign q[1]  = a_i[3]  | a_i[2];
assign q[0]  = a_i[3]  | (~a_i[2]  & a_i[1]);
assign q[3]  = a_i[7]  | a_i[6];
assign q[2]  = a_i[7]  | (~a_i[6]  & a_i[5]);
assign q[5]  = a_i[11] | a_i[10];
assign q[4]  = a_i[11] | (~a_i[10] & a_i[9]);
assign q[7]  = a_i[15] | a_i[14];
assign q[6]  = a_i[15] | (~a_i[14] & a_i[13]);
assign q[9]  = a_i[19] | a_i[18];
assign q[8]  = a_i[19] | (~a_i[18] & a_i[17]);
assign q[11] = a_i[23] | a_i[22];
assign q[10] = a_i[23] | (~a_i[22] & a_i[21]);
assign q[13] = a_i[27] | a_i[26];
assign q[12] = a_i[27] | (~a_i[26] & a_i[25]);
assign q[15] = a_i[31] | a_i[30];
assign q[14] = a_i[31] | (~a_i[30] & a_i[29]);

// ---- 8:1 select of the 2-bit low index ----
wire [7:0] w2 = s2 ? q[15:8]  : q[7:0];
wire [3:0] w1 = s1 ? w2[7:4]  : w2[3:0];
wire [1:0] w0 = s0 ? w1[3:2]  : w1[1:0];

wire [5:0] chosen = {hit, s2, s1, s0, w0[1], w0[0]};

always @(posedge clk) begin
    if (!rst_n) begin
        valid_o <= 1'b0;
        y_o <= 6'd0;
    end else begin
        valid_o <= valid_i;
        if (valid_i)
            y_o <= chosen;
    end
end
endmodule

module priority32 (
    input wire clk,
    input wire rst_n,
    input wire valid_i,
    input wire [31:0] a_i,
    input wire [31:0] b_i,
    output reg valid_o,
    output reg [5:0] y_o
);

// ---- level 1 : nibble occupancy ----
wire n0 = |a_i[3:0];
wire n1 = |a_i[7:4];
wire n2 = |a_i[11:8];
wire n3 = |a_i[15:12];
wire n4 = |a_i[19:16];
wire n5 = |a_i[23:20];
wire n6 = |a_i[27:24];
wire n7 = |a_i[31:28];

// ---- level 2/3/4 : nibble index bits ----
wire hi  = n7 | n6 | n5 | n4;                       // idx[4]
wire lo  = n3 | n2 | n1 | n0;
wire hit = hi | lo;

wire ab  = n7 | n6;
wire cd  = n5 | n4;
wire ef  = n3 | n2;
wire s1  = ab | (~cd & ef);                         // idx[3]

wire t3  = ~(n6 | n5 | n4);
wire t5  = ~(n3 | n2);
wire s0  = n7 | (~n6 & n5) | (t3 & n3) | (t3 & t5 & n1);   // idx[2]

// ---- level 1/2 : per-nibble low index bits (parallel) ----
wire [15:0] q;
assign q[1]  = a_i[3]  | a_i[2];
assign q[0]  = a_i[3]  | (~a_i[2]  & a_i[1]);
assign q[3]  = a_i[7]  | a_i[6];
assign q[2]  = a_i[7]  | (~a_i[6]  & a_i[5]);
assign q[5]  = a_i[11] | a_i[10];
assign q[4]  = a_i[11] | (~a_i[10] & a_i[9]);
assign q[7]  = a_i[15] | a_i[14];
assign q[6]  = a_i[15] | (~a_i[14] & a_i[13]);
assign q[9]  = a_i[19] | a_i[18];
assign q[8]  = a_i[19] | (~a_i[18] & a_i[17]);
assign q[11] = a_i[23] | a_i[22];
assign q[10] = a_i[23] | (~a_i[22] & a_i[21]);
assign q[13] = a_i[27] | a_i[26];
assign q[12] = a_i[27] | (~a_i[26] & a_i[25]);
assign q[15] = a_i[31] | a_i[30];
assign q[14] = a_i[31] | (~a_i[30] & a_i[29]);

// ---- 8:1 selection, selects applied in arrival order ----
wire [7:0] w2 = hi ? q[15:8] : q[7:0];
wire [3:0] w1 = s1 ? w2[7:4] : w2[3:0];
wire [1:0] w0 = s0 ? w1[3:2] : w1[1:0];

wire [5:0] chosen = {hit, hi, s1, s0, w0[1], w0[0]};

// ---- register tail : only one gate after 'chosen' ----
wire ve = rst_n & valid_i;
wire [5:0] hold = rst_n ? y_o : 6'd0;

always @(posedge clk) begin
    valid_o <= ve;
    y_o     <= ve ? chosen : hold;
end

endmodule

module priority32 (
    input wire clk,
    input wire rst_n,
    input wire valid_i,
    input wire [31:0] a_i,
    input wire [31:0] b_i,
    output reg valid_o,
    output reg [5:0] y_o
);

// ---- level 1 : nibble occupancy and nibble-local bits ----
wire n0 = |a_i[3:0];
wire n1 = |a_i[7:4];
wire n2 = |a_i[11:8];
wire n3 = |a_i[15:12];
wire n4 = |a_i[19:16];
wire n5 = |a_i[23:20];
wire n6 = |a_i[27:24];
wire n7 = |a_i[31:28];

wire u0 = a_i[3]  | a_i[2];
wire u1 = a_i[7]  | a_i[6];
wire u2 = a_i[11] | a_i[10];
wire u3 = a_i[15] | a_i[14];
wire u4 = a_i[19] | a_i[18];
wire u5 = a_i[23] | a_i[22];
wire u6 = a_i[27] | a_i[26];
wire u7 = a_i[31] | a_i[30];

wire l0 = a_i[3]  | (~a_i[2]  & a_i[1]);
wire l1 = a_i[7]  | (~a_i[6]  & a_i[5]);
wire l2 = a_i[11] | (~a_i[10] & a_i[9]);
wire l3 = a_i[15] | (~a_i[14] & a_i[13]);
wire l4 = a_i[19] | (~a_i[18] & a_i[17]);
wire l5 = a_i[23] | (~a_i[22] & a_i[21]);
wire l6 = a_i[27] | (~a_i[26] & a_i[25]);
wire l7 = a_i[31] | (~a_i[30] & a_i[29]);

// ---- level 2 : "nothing higher" masks (single NOR gates) ----
wire nb7  = ~n7;
wire nb3  = ~n3;
wire nb1  = ~n1;
wire hb5  = ~(n7 | n6);
wire hb4  = ~(n7 | n6 | n5);
wire hb3  = ~(n7 | n6 | n5 | n4);
wire eb32 = ~(n3 | n2);
wire eb54 = ~(n5 | n4);
wire m654 = ~(n6 | n5 | n4);

wire e76 = n7 | n6;
wire e32 = n3 | n2;

// ---- high index bits ----
wire s2  = n7 | n6 | n5 | n4;
wire s1  = e76 | (eb54 & e32);
wire s0  = n7 | (~n6 & n5) | (m654 & n3) | (m654 & eb32 & n1);
wire hit = s2 | n3 | n2 | n1 | n0;

// ---- low index bits : one-hot sum of products, all terms at equal depth ----
wire y1 = ((u7            ) | (u6 & nb7)) |
          ((u5 & hb5      ) | (u4 & hb4)) |
          ((u3 & hb3      ) | (u2 & hb3 & nb3)) |
          ((u1 & hb3 & eb32) | (u0 & hb3 & eb32 & nb1));

wire y0 = ((l7            ) | (l6 & nb7)) |
          ((l5 & hb5      ) | (l4 & hb4)) |
          ((l3 & hb3      ) | (l2 & hb3 & nb3)) |
          ((l1 & hb3 & eb32) | (l0 & hb3 & eb32 & nb1));

wire [5:0] chosen = {hit, s2, s1, s0, y1, y0};

always @(posedge clk) begin
    if (!rst_n) begin
        valid_o <= 1'b0;
        y_o <= 6'd0;
    end else begin
        valid_o <= valid_i;
        if (valid_i)
            y_o <= chosen;
    end
end

endmodule

module priority32 (
    input wire clk,
    input wire rst_n,
    input wire valid_i,
    input wire [31:0] a_i,
    input wire [31:0] b_i,
    output reg valid_o,
    output reg [5:0] y_o
);

// ---- level 1 : nibble occupancy and nibble-local bits ----
wire n0 = |a_i[3:0];
wire n1 = |a_i[7:4];
wire n2 = |a_i[11:8];
wire n3 = |a_i[15:12];
wire n4 = |a_i[19:16];
wire n5 = |a_i[23:20];
wire n6 = |a_i[27:24];
wire n7 = |a_i[31:28];

wire u0 = a_i[3]  | a_i[2];
wire u1 = a_i[7]  | a_i[6];
wire u2 = a_i[11] | a_i[10];
wire u3 = a_i[15] | a_i[14];
wire u4 = a_i[19] | a_i[18];
wire u5 = a_i[23] | a_i[22];
wire u6 = a_i[27] | a_i[26];
wire u7 = a_i[31] | a_i[30];

wire l0 = a_i[3]  | (~a_i[2]  & a_i[1]);
wire l1 = a_i[7]  | (~a_i[6]  & a_i[5]);
wire l2 = a_i[11] | (~a_i[10] & a_i[9]);
wire l3 = a_i[15] | (~a_i[14] & a_i[13]);
wire l4 = a_i[19] | (~a_i[18] & a_i[17]);
wire l5 = a_i[23] | (~a_i[22] & a_i[21]);
wire l6 = a_i[27] | (~a_i[26] & a_i[25]);
wire l7 = a_i[31] | (~a_i[30] & a_i[29]);

// ---- level 2 : "nothing higher" masks (single NOR gates) ----
wire nb7  = ~n7;
wire nb3  = ~n3;
wire nb1  = ~n1;
wire hb5  = ~(n7 | n6);
wire hb4  = ~(n7 | n6 | n5);
wire hb3  = ~(n7 | n6 | n5 | n4);
wire eb32 = ~(n3 | n2);
wire eb54 = ~(n5 | n4);
wire m654 = ~(n6 | n5 | n4);

wire e76 = n7 | n6;
wire e32 = n3 | n2;

// ---- high index bits ----
wire s2  = n7 | n6 | n5 | n4;
wire s1  = e76 | (eb54 & e32);
wire s0  = n7 | (~n6 & n5) | (m654 & n3) | (m654 & eb32 & n1);
wire hit = s2 | n3 | n2 | n1 | n0;

// ---- low index bits : upper/lower half factored, low fanout masks ----
wire au = u7 | (u6 & nb7) | (u5 & hb5) | (u4 & hb4);
wire cu = u3 | (u2 & nb3) | (eb32 & (u1 | (u0 & nb1)));
wire y1 = au | (hb3 & cu);

wire al = l7 | (l6 & nb7) | (l5 & hb5) | (l4 & hb4);
wire cl = l3 | (l2 & nb3) | (eb32 & (l1 | (l0 & nb1)));
wire y0 = al | (hb3 & cl);

wire [5:0] chosen = {hit, s2, s1, s0, y1, y0};

always @(posedge clk) begin
    if (!rst_n) begin
        valid_o <= 1'b0;
        y_o <= 6'd0;
    end else begin
        valid_o <= valid_i;
        if (valid_i)
            y_o <= chosen;
    end
end

endmodule
